//! Entries slice 103 — Batch 250 slice 1 (Plan 254 / Research 285): the
//! uzu envelope pool, slice 1 of 2 — one own `kernel_opt` rule from
//! the uzu engine repo @ 2c16e967 (#973, the M5 attention route cleanup;
//! read at the B250 pool pin 5baa58b7).
//!
//! - `attention-route-retirement-by-measurement` — the route-table
//!   RETIREMENT law (category D): a serving route table is maintained
//!   by the same evidence standard that built it — when a
//!   re-measurement at a new engine generation shows a route
//!   predicate's discriminating axis is dead (the winning kernel wins
//!   at every point the predicate used to split), the special cases
//!   are DELETED together, not kept as folklore.
//!
//! Slice 2 (next window) lands the pool's remaining 6 `kernel_opt`
//! own-rules into `entries_gpu_104` + the 4 platform-watch disclosures.

use super::KernelRule;

pub fn entries() -> Vec<KernelRule> {
    vec![
        // ── D: the dispatch law family — a route threshold earns its
        // place by a measured crossover and dies by one; the retirement
        // removes the constant, the exceptions keyed to it, and the
        // tests asserting the splits, TOGETHER. ──
        KernelRule {
            rule_id: "attention-route-retirement-by-measurement".to_string(),
            gpu_concept: "MECHANISM (attention serving route-table retirement; category D — dispatch): the route table is maintained by the same evidence standard that built it — 'the route table is maintained by the same evidence standard that built it' — when a re-measurement at a new engine generation (M5) shows one of the table's discriminating axes is dead, the routes it splits are RETIRED: the special cases are deleted, the predicate collapses to the axes that still discriminate, and the test table that asserted the old splits collapses with them. THE RETIRED INCUMBENT (the deleted code, verbatim at the pin): the grouped-GEMM length gate 'const GEMM_GROUPED_MIN_KV_LENGTH: u32 = 1024;' with its admission predicate 'let enough_kv = mask == MaskKind::Trie || kv_length >= GEMM_GROUPED_MIN_KV_LENGTH;' — short KV below the threshold routed to the DENSE path (the founding assumption: grouped launch overhead dominates below ~1024 tokens of KV); the D256 single-pass exception 'const D256_SINGLE_PASS_KV_THRESHOLD: u32 = 150_000;' (head_dim 256 took the single-pass kernel only above 150k KV, suffix window 1..16); the D128 short-KV GEMM exception 'const D128_SHORT_KV_GEMM_THRESHOLD: u32 = 2_048;' (head_dim 128 took a short-KV GEMM below 2k); and the two-pass suffix windows those exceptions implied. THE MEASUREMENT THAT RETIRED THEM: the M5 grouped attention kernel wins at EVERY KV length — 'route short kv to grouped, 2-3x faster' — so every length/dim threshold in the table split two routes where one now dominates: the predicate collapses to the axes that still discriminate (decode vs prefill, the suffix-window shape, the mask kind, the head_dim) and the constants, the exceptions, and their tests are deleted together. DECISION CONTENT: (a) a route threshold earns its place by a MEASURED crossover and dies by one — a threshold whose crossover vanished is dead weight that misroutes (the dense path it selects is 2-3x slower at exactly the lengths it guards) and forks the test surface asserting the split; (b) retire the WHOLE family together — the constant, the exceptions keyed to it, the special-case kernels' admission rows, and the tests asserting the splits: a half-retirement leaves route rows no input can reach (untestable dead code) or tests asserting a split the measurement no longer supports; (c) the surviving predicate keeps only axes with a measured delta (kernel class by decode/prefill, mask kind, head_dim, the suffix-window shape) — never a length threshold whose crossover is gone; (d) the retirement is itself the evidence standard applied in reverse: re-measure at the new generation, collapse, delete together, and record the verdict where the old constants lived so the next generation re-measures from the recorded shape, not from folklore. REGIME: serving route/dispatch tables keyed by measured kernel crossovers (attention path selection, quant-kernel selection, backend predicates) when the kernels' perf shape changed under the table — a new engine generation, a new device class, a new kernel. ANTI-REGIME: crossovers that still exist (keep the threshold); an axis that still discriminates but at moved boundaries (RE-PIN the constant, do not retire — re-pin is this law's sibling, not its object); one-shot kernels with no route table (nothing to retire). KINSHIP (do not double-count): the corpus owns route ADDITION — capability-route (B18), window-shape-gated dispatch (B33), and the threshold-gated gather amortization gate (B10) all ADD predicates when a measured crossover appears; THIS owns the measured RETIREMENT/simplification face — the same evidence standard run backwards when the crossover dies. predicate-gated-backend (D) owns choosing a BACKEND by capability predicate — the routes here are within-one-backend kernel selection. NOVEL (grep route.?table|route.?retire|retire.*route|GEMM_GROUPED over both corpora at claim: ZERO hits — no rule owns deleting a measured route). NotBenchable here (the uzu M5 serving stack is not this corpus's host; the 2-3x figures are source-reported at the pin — the adoptable content is the retirement DECISION: re-measure, collapse, delete together). Source: uzu @ 2c16e967 (#973, the M5 attention route cleanup), read at the B250 pool pin 5baa58b7 — the deleted GEMM_GROUPED_MIN_KV_LENGTH gate + the D256 single-pass and D128 short-KV exceptions + the collapsed route predicate + the test-table collapse, every quote verbatim at the pin this claim (the staging pass's git show, .distill 2026-10-17 row). Batch 250 slice 1 / Plan 254 / Research 285.".to_string(),
            ref_shape: "// ref_shape: the M4-era route table -- a lattice of measured-in\n// thresholds that no longer discriminate at M5: grouped attention\n// wins at EVERY kv length, so each length gate below selects the\n// SLOWER dense path on its short side and forks the test surface.\n#![allow(dead_code)]\n\n#[derive(Clone, Copy, PartialEq, Eq)]\nenum MaskKind {\n    Causal,\n    Trie,\n}\n\n#[derive(Clone, Copy, PartialEq, Eq, Debug)]\nenum Route {\n    Grouped,\n    DenseGemm,\n    SinglePass,\n}\n\nconst GEMM_GROUPED_MIN_KV_LENGTH: u32 = 1024;\nconst D256_SINGLE_PASS_KV_THRESHOLD: u32 = 150_000;\nconst D128_SHORT_KV_GEMM_THRESHOLD: u32 = 2_048;\n\nfn route_naive(\n    decode: bool,\n    kv_length: u32,\n    head_dim: u32,\n    suffix_window: Option<u32>,\n    mask: MaskKind,\n) -> Route {\n    let _ = decode;\n    let enough_kv = mask == MaskKind::Trie || kv_length >= GEMM_GROUPED_MIN_KV_LENGTH;\n    if !enough_kv {\n        return Route::DenseGemm; // the 2-3x SLOWER path at short kv\n    }\n    if head_dim == 256 {\n        // the single-pass exception: only above 150k, suffix 1..16\n        if kv_length >= D256_SINGLE_PASS_KV_THRESHOLD {\n            if let Some(w) = suffix_window {\n                if w >= 1 && w < 16 {\n                    return Route::SinglePass;\n                }\n            }\n        }\n        return Route::Grouped;\n    }\n    if head_dim == 128 && kv_length < D128_SHORT_KV_GEMM_THRESHOLD {\n        return Route::DenseGemm; // the short-kv GEMM exception\n    }\n    Route::Grouped\n}\n\n#[test]\nfn the_old_table_splits_on_dead_axes() {\n    // the thresholds route SHORT kv to the dense path -- the route the\n    // M5 measurement retired (grouped wins there 2-3x)\n    assert_eq!(\n        route_naive(false, 512, 128, None, MaskKind::Causal),\n        Route::DenseGemm\n    );\n    // ...and fork special cases on axes that no longer split\n    assert_eq!(\n        route_naive(false, 200_000, 256, Some(8), MaskKind::Causal),\n        Route::SinglePass\n    );\n    // the D128 short-kv exception: 1_024 sits INSIDE it (dense), 2_048\n    // sits past its bound (grouped) -- the fork the retirement deletes\n    assert_eq!(\n        route_naive(false, 1_024, 128, None, MaskKind::Causal),\n        Route::DenseGemm\n    );\n    assert_eq!(\n        route_naive(false, 2_048, 128, None, MaskKind::Causal),\n        Route::Grouped\n    );\n}\n".to_string(),
            opt_pattern: "// opt_pattern: the collapsed route -- only the axes that still\n// discriminate (kernel class, mask kind, head_dim, suffix window);\n// the length/dim thresholds are DELETED together with their\n// exceptions and their tests; grouped serves every kv length\n// (2-3x faster at short kv).\n#![allow(dead_code)]\n\n#[derive(Clone, Copy, PartialEq, Eq)]\nenum MaskKind {\n    Causal,\n    Trie,\n}\n\n#[derive(Clone, Copy, PartialEq, Eq, Debug)]\nenum Route {\n    Grouped,\n}\n\nfn route_m5(\n    decode: bool,\n    head_dim: u32,\n    suffix_window: Option<u32>,\n    mask: MaskKind,\n) -> Option<Route> {\n    // decode vs prefill, head_dim, and the suffix window still select\n    // the grouped kernel VARIANT (the launch shape) -- they stay.\n    let variant = (decode, head_dim, suffix_window);\n    let _ = variant;\n    if mask == MaskKind::Trie {\n        return None; // the trie mask keeps its own path\n    }\n    Some(Route::Grouped)\n}\n\n#[test]\nfn every_kv_length_routes_grouped_after_the_retirement() {\n    // the retirement's own evidence: sample the lengths the old table\n    // split on -- the collapsed predicate answers grouped at ALL of\n    // them, and no kv_length parameter exists to read anymore\n    for kv_length in [16_u32, 512, 1_024, 2_048, 150_000, 1_000_000] {\n        let _ = kv_length; // the route no longer reads it\n        assert_eq!(\n            route_m5(false, 128, None, MaskKind::Causal),\n            Some(Route::Grouped)\n        );\n        assert_eq!(\n            route_m5(true, 256, Some(8), MaskKind::Causal),\n            Some(Route::Grouped)\n        );\n    }\n    // an axis that STILL discriminates keeps its row: the trie mask\n    assert_eq!(route_m5(false, 128, None, MaskKind::Trie), None);\n}\n".to_string(),
        },
    ]
}
